const disclaimer = 'Independent study aid. RolePrep is not affiliated with or endorsed by CompTIA. Exam policies and objectives can change; verify the current official CompTIA exam objectives before booking.'

const concept = (term, definition, example, contrast) => ({ term, definition, example, contrast })
const domain = (title, summary, concepts) => ({ title, summary, concepts })

function buildTrack(config) {
  const modules = config.domains.map((item, index) => ({
    id: `${config.id}-${index + 1}`,
    number: String(index + 1).padStart(2, '0'),
    title: item.title,
    time: item.time || '75–90 min',
    activityLabel: 'CERTIFICATION PRACTICE',
    summary: item.summary,
    objectives: [
      `Explain the essential vocabulary in ${item.title.toLowerCase()}`,
      `Apply ${item.title.toLowerCase()} concepts to a practical scenario`,
      'Eliminate tempting exam distractors by explaining the underlying distinction'
    ],
    sections: item.concepts.map((entry, conceptIndex) => ({
      title: entry.term,
      paragraphs: [
        `${entry.definition} This matters because certification questions rarely test a term in isolation: they describe a goal, symptom, risk, or constraint and ask you to choose the concept or action that best fits. Start by restating the definition in your own words, then identify the clue that separates it from related ideas.`,
        `For example, ${entry.example} A common mistake is to confuse this with ${entry.contrast}. On the exam and in real work, read the entire scenario, identify what outcome is needed, choose the least risky effective action, and verify the result rather than matching on one familiar word.`
      ],
      terms: [[entry.term, entry.definition]],
      checkpoint: {
        question: `How would you recognize ${entry.term} in a scenario?`,
        answer: `Look for a situation where ${entry.example} The defining idea is: ${entry.definition}`
      },
      steps: conceptIndex === item.concepts.length - 1 ? ['Identify the desired outcome.', 'Note the evidence and constraints.', 'Name the relevant concept.', 'Choose the safest effective action.', 'Validate and document the result.'] : undefined
    })),
    command: `Teach-back drill: define ${item.concepts.map(entry => entry.term).join(', ')} without notes.`,
    commandNote: `Then create one new scenario for each term and explain why the other concepts in this module would be weaker answers.`,
    interviewQuestions: item.concepts.slice(0, 3).map(entry => ({ question: `Explain ${entry.term} and give a practical example.`, example: `${entry.definition} A practical example is when ${entry.example}` }))
  }))

  const allConcepts = config.domains.flatMap(item => item.concepts)
  const definitionQuestions = allConcepts.map((entry, index) => {
    const distractors = [1, 5, 11].map(offset => allConcepts[(index + offset) % allConcepts.length].definition)
    return { q: `Which statement best describes ${entry.term}?`, choices: [entry.definition, ...distractors], answer: 0, why: `${entry.term}: ${entry.definition}` }
  })
  const scenarioQuestions = config.domains.map((item, index) => {
    const answer = item.concepts[index % item.concepts.length]
    return { q: `Which concept best fits this situation: ${answer.example}`, choices: [answer.term, ...item.concepts.filter(entry => entry.term !== answer.term).slice(0, 3).map(entry => entry.term)], answer: 0, why: `${answer.term} is the closest match because ${answer.definition.toLowerCase()}` }
  })

  return {
    id: config.id,
    type: 'certification',
    category: `CERTIFICATION PREP · ${config.family}`,
    title: config.title,
    subtitle: config.subtitle,
    level: config.level,
    duration: config.duration,
    description: config.description,
    heroTitle: config.heroTitle,
    heroDescription: config.heroDescription,
    promptLabel: 'EXAM RECALL',
    promptInstruction: 'Answer without notes: define the concept, identify the scenario clue, choose the best action, and explain why a nearby concept is less suitable.',
    practiceEyebrow: `Apply ${config.shortTitle} skills to realistic exam scenarios`,
    practiceIntro: 'Work the problem before revealing the coaching notes. Performance-based questions reward correct sequencing, configuration judgment, troubleshooting, and validation—not vocabulary alone.',
    disclaimer,
    exam: { practiceMinutes: 50, scaled: true, ...config.exam },
    modules,
    quizQuestions: [...definitionQuestions, ...scenarioQuestions],
    glossary: allConcepts.map(entry => [entry.term, entry.definition]),
    scenarios: config.scenarios,
    featuredScenario: config.featuredScenario,
    console: config.console
  }
}

